import{_ as r,o as l,c as a,a2 as i}from"./chunks/framework.DJ9rxlUr.js";const p=JSON.parse('{"title":"3D Tiles Renderer 能力参考","description":"","frontmatter":{},"headers":[],"relativePath":"capabilities/3d-tiles-renderer.md","filePath":"capabilities/3d-tiles-renderer.md","lastUpdated":1780971066000}'),t={name:"capabilities/3d-tiles-renderer.md"};function d(s,e,n,o,c,_){return l(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="_3d-tiles-renderer-能力参考" tabindex="-1">3D Tiles Renderer 能力参考 <a class="header-anchor" href="#_3d-tiles-renderer-能力参考" aria-label="Permalink to &quot;3D Tiles Renderer 能力参考&quot;">​</a></h1><p>Tellux 基于 <code>3d-tiles-renderer</code> 提供 3D Tiles 和地形能力封装。这里先记录 Tellux 使用侧最相关的能力，完整调研可继续参考仓库中的能力文档。</p><h2 id="当前关注点" tabindex="-1">当前关注点 <a class="header-anchor" href="#当前关注点" aria-label="Permalink to &quot;当前关注点&quot;">​</a></h2><ul><li>3D Tiles 场景加载：<code>tileset.json</code>、Cesium Ion endpoint。</li><li>Cesium quantized-mesh terrain：地形根目录或 <code>layer.json</code>。</li><li>影像 overlay：XYZ、WMS、GeoJSON、MVT 等图层贴到地形或裸球表面。</li><li>LOD 与缓存：通过 tiles renderer 的更新流程参与主渲染循环。</li><li>采样：结合已加载瓦片、地形 availability 和临时局部加载区域做高度查询。</li></ul><h2 id="tellux-封装边界" tabindex="-1">Tellux 封装边界 <a class="header-anchor" href="#tellux-封装边界" aria-label="Permalink to &quot;Tellux 封装边界&quot;">​</a></h2><p>Tellux 主要做 API 使用侧的易用性封装，不重新实现底层 3D Tiles 解析、瓦片调度或地理坐标转换核心。</p><p>更底层的插件、overlay 和 renderer 能力仍以 <code>3d-tiles-renderer</code> 文档和源码为准。</p>',7)])])}const T=r(t,[["render",d]]);export{p as __pageData,T as default};
